-- Insert Quiz Questions for Lesson: How to Reply the Right Way

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'how-to-reply' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson how-to-reply not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the three parts of the reply formula?', 
    '["Greet, Explain, Close","Acknowledge, Answer, Advance","Introduce, Describe, Finish","Hello, Inform, Goodbye"]'::jsonb,
    'Acknowledge, Answer, Advance',
    'The formula is Acknowledge (let them know you saw the message), Answer (respond to their question), Advance (give a clear next step).', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the purpose of the ''Advance'' step?', 
    '["To end the conversation","To give them one clear next step to take","To ask multiple questions","To promote a different product"]'::jsonb,
    'To give them one clear next step to take',
    'The Advance step moves the conversation forward by giving the contact one specific action to take, like booking a call or answering a question.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should replies be short and clear?', 
    '["Longer replies are always better","Short, clear replies are more likely to get a response","The system limits message length","It doesn''t matter how long replies are"]'::jsonb,
    'Short, clear replies are more likely to get a response',
    'Short, focused replies are easier to read and respond to. They respect the recipient''s time and make it clear what action to take next.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
